index 31325f7..20181aa 100644
--- a/src/main/java/hotel/reservations/ReservationService.java
+++ b/src/main/java/hotel/reservations/ReservationService.java
@@ -5,6 +5,8 @@ import hotel.messages.EmailSender;
 import hotel.rooms.Room;
 import hotel.rooms.Rooms;
 import java.math.BigDecimal;
+import java.time.DayOfWeek;
+import java.time.temporal.ChronoUnit;

 /** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 public final class ReservationService {
@@ -31,6 +33,7 @@ public final class ReservationService {
         if (request.guests() < 1) {
             throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
         }
+        validateRatePlan(request);
         Room room = rooms.find(request.roomNumber())
                 .orElseThrow(() -> new HotelException(
                         ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
@@ -43,10 +46,42 @@ public final class ReservationService {
             throw new HotelException(
                     ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
         }
-        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
+        Price price = priceCalculator.calculate(
+                room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
         return store.add(request, price);
     }

+    private void validateRatePlan(NewReservation request) {
+        if (request.ratePlan() == RatePlan.CORPORATE) {
+            if (request.companyCode() == null || request.companyCode().isBlank()) {
+                throw new HotelException(ErrorCode.INVALID_REQUEST, "company code is required for corporate rate");
+            }
+            if (!PriceCalculator.CORPORATE_DISCOUNTS.containsKey(request.companyCode())) {
+                throw new HotelException(ErrorCode.INVALID_REQUEST, "invalid company code");
+            }
+        }
+
+        if (request.ratePlan() == RatePlan.WEEKEND_PACKAGE) {
+            long nights = ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
+            if (nights != 2) {
+                throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package requires exactly 2 nights");
+            }
+            if (request.checkIn().getDayOfWeek() != DayOfWeek.FRIDAY) {
+                throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package must start on Friday");
+            }
+            if (request.checkOut().getDayOfWeek() != DayOfWeek.SUNDAY) {
+                throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package must end on Sunday");
+            }
+        }
+
+        if (request.ratePlan() == RatePlan.LONG_STAY) {
+            long nights = ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
+            if (nights < 7) {
+                throw new HotelException(ErrorCode.INVALID_REQUEST, "long stay requires at least 7 nights");
+            }
+        }
+    }
+
     public Reservation find(long reservationId) {
         return store.find(reservationId)
                 .orElseThrow(() -> new HotelException(
@@ -82,6 +117,9 @@ public final class ReservationService {
         BigDecimal refund = switch (reservation.ratePlan()) {
             case STANDARD -> reservation.amountPaid();
             case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
+            case CORPORATE -> reservation.amountPaid();
+            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().multiply(new BigDecimal("0.5")));
+            case LONG_STAY -> reservation.amountPaid();
         };
         reservation.cancel(refund);
         store.update(reservation);
