    17	public final class PriceCalculator {
    18	
    19	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    20	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    21	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
    22	
    23	    static final Map<String, BigDecimal> CORPORATE_DISCOUNTS = Map.of(
    24	            "TECNOSUL", new BigDecimal("0.12"),
    25	            "AGROVALE", new BigDecimal("0.18"),
    26	            "FARMAVIDA", new BigDecimal("0.25"));
    27	
    28	    static final Map<RoomType, BigDecimal> WEEKEND_PACKAGE_PRICES = Map.of(
    29	            RoomType.STANDARD, new BigDecimal("520.00"),
    30	            RoomType.DELUXE, new BigDecimal("820.00"),
    31	            RoomType.SUITE, new BigDecimal("1200.00"));
    32	
    33	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
    34	        if (ratePlan == RatePlan.WEEKEND_PACKAGE) {
    35	            BigDecimal packagePrice = WEEKEND_PACKAGE_PRICES.get(room.type());
    36	            return new Price(2, packagePrice, cents(BigDecimal.ZERO), packagePrice);
    37	        }
    38	
    39	        int nights = 0;
    40	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    41	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    42	            subtotal = subtotal.add(nightPrice(room, night));
    43	            nights++;
    44	        }
    45	
    46	        BigDecimal discount = switch (ratePlan) {
    47	            case STANDARD -> cents(BigDecimal.ZERO);
    48	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    49	            case CORPORATE -> cents(subtotal.multiply(CORPORATE_DISCOUNTS.get(companyCode)));
    50	            case LONG_STAY -> cents(subtotal.multiply(LONG_STAY_DISCOUNT));
    51	            case WEEKEND_PACKAGE -> cents(BigDecimal.ZERO);
    52	        };
    53	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    54	    }
