    56	    BigDecimal nightPrice(Room room, LocalDate night) {
    57	        BigDecimal nightlyRate = room.nightlyRate();
    58	        if (isHighSeason(night)) {
    59	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    60	        }
    61	        return cents(nightlyRate);
    62	    }
