    68	                || month == Month.FEBRUARY
    69	                || month == Month.JULY
    70	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    71	    }
    72	
    73	    static BigDecimal cents(BigDecimal value) {
    74	        return value.setScale(2, RoundingMode.HALF_EVEN);
    75	    }
